-- The Blood Furnace: Felguard Annihilators and the Orc Captives of the cells.
--
-- The six elites in front of Keli'dan stand where TrinityCore 3.3.5 and AzerothCore both put
-- Felguard Annihilators (17400), but SkyFire spawned the weaker Felguard Brute (18894) there.
-- Swap the entry; the guids are not referenced by addons, formations or SmartAI.
UPDATE `creature` SET `id` = 17400 WHERE `guid` IN (3221, 3222, 3223, 3224, 3226, 3227) AND `id` = 18894;

-- 38 Orc Captives (17416) of The Maker's cells, spawned in 3.3.5 (sniffed build 11159) and by AzerothCore;
-- SkyFire had none, so the cells stood empty. Never summoned by a script. Positions from TrinityCore.
DELETE FROM `creature` WHERE `guid` BETWEEN 8319000 AND 8319037;

-- The captives only stand in their cells: passive, like in 3.3.5.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` = 17416 AND `AIName` = '' AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `entryorguid` = 17416 AND `source_type` = 0;
